import json
from typing import List

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        # Precompute smallest prime factor (SPF) for all numbers up to 10^6
        MAX_VAL = 1000000
        spf = list(range(MAX_VAL + 1))

        # Sieve of Eratosthenes to find SPF
        # We only need to iterate up to sqrt(MAX_VAL)
        for i in range(2, int(MAX_VAL**0.5) + 1):
            if spf[i] == i:
                # i is prime, mark all its multiples
                for j in range(i*i, MAX_VAL + 1, i):
                    if spf[j] == j:
                        spf[j] = i

        n = len(nums)
        if n == 0:
            return 0

        # Process from right to left
        # We want to maintain nums[i] <= nums[i+1]
        # For the last element, we keep it as is to maximize the limit for the previous element
        limit = nums[-1]
        ops = 0

        for i in range(n - 2, -1, -1):
            if nums[i] <= limit:
                # We can keep nums[i] as is
                limit = nums[i]
            else:
                # We must reduce nums[i]
                # The only possible reduction is to spf[nums[i]]
                reduced_val = spf[nums[i]]
                if reduced_val <= limit:
                    limit = reduced_val
                    ops += 1
                else:
                    # Cannot satisfy the condition
                    return -1

        return ops

if __name__ == "__main__":
    try:
        input_data = input().strip()
        if not input_data:
            print(0)
        else:
            nums = json.loads(input_data)
            solution = Solution()
            result = solution.minOperations(nums)
            print(result)
    except Exception:
        # In case of any unexpected error, print 0 or handle appropriately
        # Given constraints, this block is mainly for robustness
        print(0)
