import sys
import json
from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Filter out numbers greater than threshold as they cannot form edges
        # with any other number (since lcm(a, b) >= max(a, b))
        # These numbers will each form their own component.
        isolated_count = 0
        valid_nums = []
        for x in nums:
            if x > threshold:
                isolated_count += 1
            else:
                valid_nums.append(x)

        # If no numbers are <= threshold, return the count of isolated numbers
        if not valid_nums:
            return isolated_count

        # Initialize DSU for numbers 1 to threshold
        # We use 1-based indexing for convenience, so size is threshold + 1
        parent = list(range(threshold + 1))
        rank = [0] * (threshold + 1)

        def find(i):
            path = []
            while parent[i] != i:
                path.append(i)
                i = parent[i]
            for node in path:
                parent[node] = i
            return i

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if rank[root_i] < rank[root_j]:
                    root_i, root_j = root_j, root_i
                parent[root_j] = root_i
                if rank[root_i] == rank[root_j]:
                    rank[root_i] += 1
                return True
            return False

        # first_divisor[k] stores the first number from valid_nums that divides k
        first_divisor = [0] * (threshold + 1)

        # For each number x in valid_nums, connect it to all its multiples m <= threshold
        # This effectively connects all divisors of m that are in valid_nums
        for x in valid_nums:
            for m in range(x, threshold + 1, x):
                if first_divisor[m] == 0:
                    first_divisor[m] = x
                else:
                    union(x, first_divisor[m])

        # Count the number of unique roots for numbers in valid_nums
        roots = set()
        for x in valid_nums:
            roots.add(find(x))

        return isolated_count + len(roots)

if __name__ == "__main__":
    input_data = sys.stdin.read().splitlines()
    # Filter out empty lines
    lines = [line.strip() for line in input_data if line.strip()]
    if len(lines) >= 2:
        nums = json.loads(lines[0])
        threshold = int(lines[1])
        solution = Solution()
        result = solution.countComponents(nums, threshold)
        print(result)
